//! `:help` / `Space ?` buffer decoration (0088 §2, U10; 0112): the help
//! text and its typed lines are generated by `editor/help`; here each
//! line gets house style by its [`LineKind`] — one accent, the keycap
//! idiom over the key column, section rules in the faint border ink,
//! unavailable rows muted italic — through the same typed-decoration
//! pattern the git surfaces use (0010 §5), never a special-purpose
//! renderer fork. The spans' concatenated content keeps the buffer
//! line's exact bytes, so search, yank and the caret keep reading the
//! real buffer.

use ratatui::style::{Modifier, Style};
use ratatui::text::Span;

use super::style::Tokens;
use crate::editor::help::{HelpPage, LineKind};

/// Section rules read `─ Title ─────`.
const RULE: &str = "─ ";

pub(crate) fn line_spans(
    t: &Tokens,
    page: &HelpPage,
    line: usize,
    text: &str,
    width: usize,
) -> Vec<Span<'static>> {
    match page.lines.get(line) {
        Some(LineKind::Hints { .. }) => {
            // the header: name bold, the rest quiet
            let (name, rest) = text.split_at(text.find(" · ").unwrap_or(text.len()));
            vec![
                Span::styled(
                    name.to_string(),
                    Style::default().fg(t.text).add_modifier(Modifier::BOLD),
                ),
                Span::styled(rest.to_string(), Style::default().fg(t.muted)),
            ]
        }
        Some(LineKind::Heading) => {
            let rest = text.strip_prefix(RULE).unwrap_or(text);
            let title_end = rest.find(" ─").unwrap_or(rest.len());
            let (title, rule) = rest.split_at(title_end);
            let pad = width.saturating_sub(text.chars().count());
            vec![
                Span::styled(RULE.to_string(), Style::default().fg(t.faint)),
                Span::styled(
                    title.to_string(),
                    Style::default().fg(t.text).add_modifier(Modifier::BOLD),
                ),
                Span::styled(
                    format!("{rule}{}", "─".repeat(pad)),
                    Style::default().fg(t.faint),
                ),
            ]
        }
        Some(LineKind::Entry { keys, planned, .. }) if keys.end <= text.len() => {
            let body = if *planned {
                Style::default().fg(t.muted).add_modifier(Modifier::ITALIC)
            } else {
                Style::default().fg(t.text)
            };
            // the keycap: the padded column, one cell either side
            let cap_start = keys.start.saturating_sub(1);
            let desc_start = text[keys.end..]
                .find(|c: char| c != ' ')
                .map_or(text.len(), |at| keys.end + at);
            let cap_end = desc_start.saturating_sub(2).max(keys.end);
            let cap = if *planned {
                Style::default().fg(t.muted).bg(t.raised)
            } else {
                Style::default()
                    .fg(t.accent)
                    .bg(t.raised)
                    .add_modifier(Modifier::BOLD)
            };
            vec![
                Span::styled(text[..cap_start].to_string(), Style::default()),
                Span::styled(text[cap_start..cap_end].to_string(), cap),
                Span::styled(text[cap_end..desc_start].to_string(), Style::default()),
                Span::styled(text[desc_start..].to_string(), body),
            ]
        }
        _ => vec![Span::styled(text.to_string(), Style::default().fg(t.text))],
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use strop_engine::editor::Editor;

    fn tokens() -> Tokens {
        Tokens::new(strop_core::theme::ThemeId::Hone)
    }

    fn joined(spans: &[Span<'static>]) -> String {
        spans.iter().map(|span| span.content.as_ref()).collect()
    }

    #[test]
    fn rows_keep_their_bytes_and_wear_one_accent() {
        let t = tokens();
        let mut editor = Editor::new(strop_core::Buffer::from_text("x\n"));
        editor.feed_text(":help\r");
        let page = editor.help_page(editor.current()).expect("help").clone();
        let buf = editor.buf();
        let line = |at: usize| buf.text().line(at).to_string().trim_end().to_owned();
        let header = line_spans(&t, &page, 0, &line(0), 80);
        assert_eq!(joined(&header), line(0));
        assert_eq!(header[0].style.fg, Some(t.text));

        let rule = line_spans(&t, &page, 2, &line(2), 80);
        assert!(joined(&rule).starts_with("─ Moving ──"));
        assert_eq!(rule[1].content, "Moving");
        assert_eq!(rule[0].style.fg, Some(t.faint));
        assert_eq!(rule[1].style.fg, Some(t.text));

        let row = line_spans(&t, &page, 3, &line(3), 80);
        assert_eq!(joined(&row), line(3));
        assert!(row[1].content.contains("h j k l"));
        assert_eq!(row[1].style.fg, Some(t.accent));
        assert_eq!(row[1].style.bg, Some(t.raised));
        assert_eq!(row[3].style.fg, Some(t.text));

        let soon = (0..page.lines.len())
            .find(|&at| matches!(page.lines[at], LineKind::Entry { planned: true, .. }));
        if let Some(at) = soon {
            let spans = line_spans(&t, &page, at, &line(at), 80);
            assert!(spans.iter().all(|span| span.style.fg != Some(t.accent)));
            assert!(spans[3].style.add_modifier.contains(Modifier::ITALIC));
        }
    }
}
